CREATE TABLE IF NOT EXISTS seller_media (id CHAR(36) PRIMARY KEY,seller_id CHAR(36) NOT NULL,media_type ENUM('PROFILE','BANNER') NOT NULL,url TEXT NOT NULL,public_id VARCHAR(255) NOT NULL,format VARCHAR(20) NOT NULL,file_size BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT seller_media_seller_fk FOREIGN KEY(seller_id) REFERENCES sellers(id) ON DELETE CASCADE,UNIQUE KEY seller_media_type_unique(seller_id,media_type));
